// === Tab: mySketch ===
//Made by 16384 - Feb. 2020

let num = 1500;
let pos, vel;
let bakedCSVelLength = 5;
let bakedCSVel = [];

function setup() {
	createCanvas(windowWidth, windowHeight);
	background(0);

	resetParticles();
	colorMode(HSB);
	for(let i = 0; i < bakedCSVelLength; i++) {
		bakedCSVel[i] = createVector(cos(i * (TWO_PI/bakedCSVelLength)), sin(i * (TWO_PI/bakedCSVelLength))).mult(0.1);
	}
}

function draw() {
	if (frameCount == 40) print(millis());
	for (let i = 0; i < pos.length; i++) {
		pos[i].add(vel[i]);
		vel[i].add(bakedCSVel[floor(random(bakedCSVelLength))]);

		//Next line sets the stroke color, smoothly randomized in respect to the current time, just to add some diversity 
		stroke((frameCount / 2 + map(noise(minute()) + noise(second()/100) * 0.1, 0, 1.1, 0, 255)) % 255, 255, 255);
		line(pos[i].x, pos[i].y, pos[i].x + vel[i].x * 2, pos[i].y + vel[i].y * 2);
	}
}

function keyPressed() {
	if (key == 'r') resetParticles();		
}

function resetParticles() {
	pos = [];
		vel = [];
		for (let i = 0; i < num; i++) {
			pos[i] = createVector(width / 2, height / 2);
			vel[i] = createVector(0, 0);
		}
	background(0);
}

